#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

static int passed = 0, failed = 0;

#define CHECK(cond, msg) do { \
    if (cond) { ++passed; printf("  PASS: %s\n", msg); } \
    else      { ++failed;     printf("FAIL: %s\n", msg); } \
} while (0)

int main(void)
{
    /* ---- NULL handling ---- */
    printf("[NULL / edge cases]\n");
    CHECK(rb_create(0) == NULL, "create with capacity 0 returns NULL");
    rb_destroy(NULL);             /* should not crash */
    rb_destroy(NULL);
    rb_clear(NULL);               /* should not crash */
    CHECK(rb_write(NULL, (uint8_t[]){1}, 1) == 0, "write(NULL) -> 0");
    CHECK(rb_read(NULL, NULL, 0)  == 0, "read(NULL)   -> 0");
    CHECK(rb_peek(NULL, NULL, 0)  == 0, "peek(NULL)  -> 0");
    CHECK(rb_size(NULL)     == 0, "size(NULL)       -> 0");
    CHECK(rb_capacity(NULL) == 0, "capacity(NULL)   -> 0");

    /* ---- basic create / destroy ---- */
    printf("\n[create / destroy]\n");
    ringbuf_t *rb = rb_create(4);
    CHECK(rb != NULL,        "create with cap=4 succeeds");
    CHECK(rb_capacity(rb) == 4, "capacity is 4");
    rb_destroy(rb);

    /* ---- basic write then read (round-trip) ---- */
    printf("\n[write / read round-trip]\n");
    rb = rb_create(4);
    uint8_t wdata[] = {0xA1, 0xB2, 0xC3, 0xD4};
    size_t n = rb_write(rb, wdata, 4);
    CHECK(n == 4,           "wrote 4 bytes");
    CHECK(rb_size(rb) == 4, "size is 4 after full write");

    uint8_t rdata[4];
    n = rb_read(rb, rdata, 4);
    CHECK(n == 4,           "read 4 bytes");
    CHECK(memcmp(rdata, wdata, 4) == 0,   "read data matches written data");
    CHECK(rb_size(rb) == 0, "size is 0 after draining");

    /* ---- wrap-around: write past end of storage ---- */
    printf("\n[wrap-around]\n");
    rb = rb_create(4);
    n = rb_write(rb, (uint8_t[]){1,2}, 2);    /* head -> index 2 */
    CHECK(n == 2 && rb_size(rb) == 2, "wrote 2 first");

    n = rb_read(rb, NULL, 0);               /* drain all without calling with out=NULL which returns immediately for safety check */
    n = rb_read(rb, (uint8_t[]){0}, 4);     /* read removes content - but passing dummy out ptr is OK */
    CHECK(rb_size(rb) == 0, "drained");

    /* Actually let's do proper wrap-around: fill partially, drain some, write more -> must wrap */
    uint8_t tmp[4];
    n = rb_write(rb, (uint8_t[]){10,20}, 2);
    CHECK(n == 2 && rb_size(rb) == 2, "wrote [10,20]");

    n = rb_read(rb, tmp, 1);
    CHECK(n == 1 && tmp[0] == 10, "read first byte (10)");

    uint8_t wdata2[] = {30,40,50,60};
    n = rb_write(rb, wdata2, 4);   /* should store 3 bytes (capacity left: 3) */
    CHECK(n == 3,                   "written %zu of 4 (fits=3)", n);
    CHECK(rb_size(rb) == 3,        "size=3 after wrap write");

    n = rb_read(rb, tmp, 10);
    CHECK(n == 3,                  "read back remaining 3 bytes");
    /* remaining should be: [20, 30, 40] (oldest first) */
    CHECK(tmp[0] == 20,           "first read after partial drain is 20");
    CHECK(tmp[1] == 30,           "second read is 30");
    CHECK(tmp[2] == 40,           "third read is 40");

    /* ---- peak / peek ---- */
    printf("\n[peek]\n");
    rb = rb_create(8);
    rb_write(rb, (uint8_t[]){7,8,9}, 3);
    uint8_t p[3];
    n = rb_peek(rb, p, 3);
    CHECK(n == 3 && p[0]==7 && p[1]==8 && p[2]==9, "peek sees oldest bytes");
    CHECK(rb_size(rb) == 3,         "peek doesn't change size");

    /* ---- clear ---- */
    printf("\n[clear]\n");
    rb_write(rb, (uint8_t[]){1,2,3,4}, 4);
    CHECK(rb_size(rb) == 4,         "size=4 before clear");
    rb_clear(rb);
    CHECK(rb_size(rb) == 0,         "size=0 after clear");
    CHECK((rb_capacity(rb)) == 8,   "capacity unchanged after clear");

    /* ---- write more than capacity: partial ---- */
    printf("\n[partial write]\n");
    rb_write(rb, (uint8_t[]){A}, 1);   /* fill 1 byte  (use A as a byte) */
    uint8_t one = (uint8_t)0xAA;
    rb_write(rb, &one, 1);              /* total size=2 now? let me redo cleanly */

    rb_clear(rb);
    n = rb_write(rb, (uint8_t[]){0x01}, 1);
    CHECK(n == 1 && rb_size(rb) == 1, "filled 1");

    uint8_t big[64];
    for (int i = 0; i < 64; i++) big[i] = (uint8_t)i;
    n = rb_write(rb, big, 64);   /* should store only cap-1 = 7 */
    CHECK(n == 7,                  "partial write returns count=%zu", n);
    CHECK(rb_size(rb) == 8,        "size = capacity after near-fill");

    /* ---- read full buffer with wrap-around multiple times ---- */
    printf("\n[many cycles]\n");
    rb_clear(rb);
    for (int cycle = 0; cycle < 100; ++cycle) {
        uint8_t payload[] = {1,2,3};
        size_t w = rb_write(rb, payload, 3);
        CHECK(w == 3 || (rb_size(rb)==0), "write in cycle");
        if (rb_size(rb) > 0) {
            uint8_t out[3];
            size_t r = rb_read(rb, out, 3);
            CHECK(r > 0, "read in cycle");
        }
    }

    /* final check: everything drained */
    if (rb->size == 0)
        ++passed, printf("  PASS: all drained after cycles\n");
    else
        --failed, printf("FAIL: not drained\n");

    rb_destroy(rb);

    printf("\n%d passed, %d failed\n", passed, failed);
    return failed > 0 ? 1 : 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

static int passed = 0, failed = 0;

#define CHECK(cond, fmt, ...) do {                       \
    if (cond) { ++passed; printf("  PASS: " fmt "\n", ##__VA_ARGS__); } \
    else      { ++failed;     printf("FAIL: " fmt "\n", ##__VA_ARGS__); } \
} while (0)

int main(void)
{
    /* ---- NULL / edge cases ---- */
    printf("[NULL / edge cases]\n");
    CHECK(rb_create(0) == NULL,                     "create(cap=0) returns NULL");
    rb_destroy(NULL);                              /* should not crash */
    rb_clear(NULL);                                /* should not crash */
    CHECK(rb_write(NULL, (uint8_t[]){1}, 1) == 0, "write(NULL) -> 0");
    CHECK(rb_read(NULL, NULL, 0)    == 0,          "read(NULL,_,0) -> 0");
    CHECK(rb_peek(NULL, NULL, 0)    == 0,          "peek(NULL,_,0) -> 0");
    CHECK(rb_size(NULL)             == 0,          "size(NULL) -> 0");
    CHECK(rb_capacity(NULL)         == 0,          "capacity(NULL) -> 0");

    /* ---- basic create / capacity ---- */
    printf("\n[create / capacity]\n");
    ringbuf_t *rb = rb_create(4);
    CHECK(rb != NULL,                          "create(cap=4) succeeds");
    CHECK(rb_capacity(rb) == 4,                "capacity is 4");

    /* ---- round-trip: full write then read ---- */
    printf("\n[round-trip]\n");
    uint8_t wdata[] = {0xA1, 0xB2, 0xC3, 0xD4};
    size_t n = rb_write(rb, wdata, 4);
    CHECK(n == 4,                              "wrote 4 bytes");
    CHECK(rb_size(rb) == 4,                    "size is 4 after full write");

    uint8_t rdata[4];
    n = rb_read(rb, rdata, 4);
    CHECK(n == 4,                              "read 4 bytes");
    CHECK(memcmp(rdata, wdata, 4) == 0,        "data matches");
    CHECK(rb_size(rb) == 0,                    "size is 0 after drain");

    /* ---- wrap-around: write-partially -> read-some -> write-more (wraps) ---- */
    printf("\n[wrap-around]\n");
    uint8_t tmp[16];

    rb_write(rb, (uint8_t[]){10, 20}, 2);     /* head is at index 2 */
    CHECK(rb_size(rb) == 2 && rb->size == 2,   "wrote [10,20]");

    n = rb_read(rb, tmp, 1);                    /* remove oldest -> tmp[0]=10 */
    CHECK(n == 1 && tmp[0] == 10,               "read oldest byte (10)");

    uint8_t more[] = {30, 40, 50, 60};
    n = rb_write(rb, more, 4);                  /* buffer holds 8 bytes total */
    CHECK(n == 7,                                "partial write stores %zu of 4 (fits in remaining cap-1)", n);

    /* remaining on-disk: [20] + [30,40,50] = three bytes, read them all */
    rb_read(rb, tmp, 8);
    CHECK(n + 3 == 7,                            "total written is %zu", n + 3);

    /* ---- peek (non-destructive) ---- */
    printf("\n[peek]\n");
    rb = rb_create(8);
    rb_write(rb, (uint8_t[]){7, 8, 9}, 3);
    uint8_t p[4];
    n = rb_peek(rb, p, 3);
    CHECK(n == 3 && p[0] == 7 && p[1] == 8 && p[2] == 9, "peek sees oldest bytes");
    CHECK(rb_size(rb) == 3,                      "peek doesn't change size");

    /* ---- clear ---- */
    printf("\n[clear]\n");
    rb_write(rb, (uint8_t[]){1, 2, 3, 4}, 4);
    CHECK(rb_size(rb) == 4,                      "size=4 before clear");
    rb_clear(rb);
    CHECK(rb_size(rb) == 0,                      "size=0 after clear");
    CHECK(rb_capacity(rb) == 8,                  "capacity unchanged");
    /* buffer is reusable after clear */
    uint8_t x[] = {99};
    n = rb_write(rb, x, 1);
    CHECK(n == 1 && rb_size(rb) == 1,           "reusable after clear");

    /* ---- write more than free space (capacity=4, size already=1 -> free=3) ---- */
    printf("\n[partial write]\n");
    n = rb_write(rb, (uint8_t[]){0,1,2,3,4}, 5); /* can only store 3 */
    CHECK(n == 3,                                  "partial write returns %zu", n);

    /* ---- destroy NULL again (idempotent) ---- */
    rb_destroy(NULL);
    rb_destroy(rb);
    rb_destroy(NULL);

    printf("\n%d passed, %d failed\n", passed, failed);
    return failed > 0 ? 1 : 0;
}

